    '1aa36213cb676fd5baad5edc2bee4fbe117a778b' => ['name' => 'Výskumníci (aliancia)', 'description' => 'o 10% rýchlejšia cesta do cieľa expedície<br />o 5% väčšie planéty pre kolonizáciu<br />Prístup k systémovým teleskopom: za 40,000 j. deutéria dokážu sledovať pohyby flotíl v celej sústave, kým sú v dosahu.', 'duration_label' => 'za 40,000 j. deutéria dokážu sledovať pohyby flotíl v celej sústave, kým sú v dosahu.', 'extended_description' => 'Keď spolupracuje veľa skvelých mozgov, vznikajú úžasné vynálezy. Aliancia výskumníkov nielen dokáže pri kolonizácii lepšie využiť objavené planéty, ale ich lode sú na expedíciách rýchlejšie. Spoločne majú prístup k systémovým teleskopom, ktoré je možné použiť na skenovanie pohybov flotíl v celých sústavách.'],
    '6c9fe5e35bdad0d4e3382eb6a5aeac6bc8263752' => ['name' => 'Obchodníci (aliancia)', 'description' => 'o 10% rýchlejšie transportéry<br />o 5% vyššia produkcia zdrojov a energie<br />o 10% väčšia kapacita skladov na mesiacoch a planétach', 'duration_label' => 'Trvalé', 'extended_description' => 'Obchodné aliancie sú prínosom pre všetky zúčastnené strany a nikto to nevie lepšie ako aliancia obchodníkov. Ich transportéry lietajú rýchlejšie a procesy výroby energie a zdrojov boli optimalizované, takže dokážu zarobiť veľké peniaze. Vďaka vylepšenej logistike majú tiež viac skladovacieho priestoru na planétach a mesiacoch.'],
    '9b48e257cbef6c5df0f03a47cead7f9abda3d437' => ['name' => 'Bojovníci (aliancia)', 'description' => 'o 10% rýchlejší presun medzi členmi aliancie<br />úroveň bojového výskumu +1<br />úroveň špionážneho výskumu +1<br />Prístup k systémovej špionáži: vysiela zadaný počet špionážnych sond na sledovanie celej sústavy. Môžeš nastaviť typ vesmírnych telies na prieskum, čas od poslednej špionáže alebo určitú aktivitu hráča.', 'duration_label' => 'vysiela zadaný počet špionážnych sond na sledovanie celej sústavy. Môžeš nastaviť typ vesmírnych telies na prieskum, čas od poslednej špionáže alebo určitú aktivitu hráča.', 'extended_description' => 'Aj najmocnejší bojovníci musia niekedy uzavrieť dohodu, aby mohli spoločne vládnuť nad galaxiou. Špionážna technológia, ktorá je ich zväzu k dispozícii, umožňuje odhaliť vhodné ciele pre ľahké ovládnutie. Spoločne je ich technológia ešte silnejšia a sú pripravení na všetko.'],
    'dc34fa00ba914ffab0031ac3f165e26f553d7809' => ['name' => 'Avatar: Laserová mačka', 'description' => 'Výberom tohto avatara v profile hráča ho môžeš použiť a dodať svojmu profilu osobný vzhľad. Tento predmet bude odomknutý pre všetky vesmíry na tvojom účte. Upozorňujeme, že synchronizácia medzi vesmírmi môže trvať určitý čas.', 'duration_label' => 'Trvalé', 'extended_description' => 'Mačky a lasery sú neoddeliteľné spojenie – teraz môžeš svoj profil vybaviť tým najlepším z oboch svetov!'],
    '1c497ef926d674f2df9d96cfc58fe12f97cf4025' => ['name' => 'Avatar: Malý mimozemšťan', 'description' => 'Výberom tohto avatara v profile hráča ho môžeš použiť a dodať svojmu profilu osobný vzhľad. Tento predmet bude odomknutý pre všetky vesmíry na tvojom účte. Upozorňujeme, že synchronizácia medzi vesmírmi môže trvať určitý čas.', 'duration_label' => 'Trvalé', 'extended_description' => 'Nové formy inteligentného života sa neustále objavujú v obrovských hlbinách vonkajšieho vesmíru. Niektoré z nich sú úplne odlišné od ľudí a majú svoje silné a slabé stránky.'],
    'fd3b0789b5dca99e9d5b251f8bae0760ce52dea6' => ['name' => 'Avatar: Vylepšený', 'description' => 'Výberom tohto avatara v profile hráča ho môžeš použiť a dodať svojmu profilu osobný vzhľad. Tento predmet bude odomknutý pre všetky vesmíry na tvojom účte. Upozorňujeme, že synchronizácia medzi vesmírmi môže trvať určitý čas.', 'duration_label' => 'Trvalé', 'extended_description' => 'Veda už dávno prekročila limity krehkého ľudského tela. Implantáty a iné vysoko technologické vylepšenia ti umožňujú byť rýchlejší, odolnejší a silnejší než ostatní.'],
    '003db2a3d693c2d889864b76ad122b274bfd641b' => ['name' => 'Avatar: Beztiažový', 'description' => 'Výberom tohto avatara v profile hráča ho môžeš použiť a dodať svojmu profilu osobný vzhľad. Tento predmet bude odomknutý pre všetky vesmíry na tvojom účte. Upozorňujeme, že synchronizácia medzi vesmírmi môže trvať určitý čas.', 'duration_label' => 'Trvalé', 'extended_description' => 'Prvý výstup do otvoreného vesmíru je veľký míľnik v živote každého mladého astronauta bez ohľadu na druh. Ten pocit vznášania sa medzi hviezdami, zatiaľ čo sa pozeráš smerom dole na svoju maličkú domovskú planétu, s tebou zostane po zvyšok života.'],
    '8d514b69eb04a57495bab0c8f4b80f58294a7b17' => ['name' => 'Avatar: Ľadovo chladný', 'description' => 'Výberom tohto avatara v profile hráča ho môžeš použiť a dodať svojmu profilu osobný vzhľad. Tento predmet bude odomknutý pre všetky vesmíry na tvojom účte. Upozorňujeme, že synchronizácia medzi vesmírmi môže trvať určitý čas.', 'duration_label' => 'Trvalé', 'extended_description' => 'Ľadové planéty sú cenené pre svoje bohaté zásoby deutéria, ale niekedy je potrebné zvýšiť úroveň bezpečnosti. Kto vie, čo sa skrýva v tom všetkom ľade a snehu...'],
    '83c4e79697a264462e3ca2e8567307e7f1d7954b' => ['name' => 'Avatar: Kyberpriestor', 'description' => 'Výberom tohto avatara v profile hráča ho môžeš použiť a dodať svojmu profilu osobný vzhľad. Tento predmet bude odomknutý pre všetky vesmíry na tvojom účte. Upozorňujeme, že synchronizácia medzi vesmírmi môže trvať určitý čas.', 'duration_label' => 'Trvalé', 'extended_description' => 'Mnohí mladí nájomní strelci, ktorí dúfajú, že si zarobia poriadny balík medzi hviezdami, si počas svojej kariéry vytvoria vlastný štýl. To im pomáha získať si reputáciu a zvýšiť svoje postavenie v pochybnejších kruhoch.'],
    '2d7de180f3f3d191982294d2f8c1cd7507e90cb4' => ['name' => 'Avatar: Retro mačičky', 'description' => 'Výberom tohto avatara v profile hráča ho môžeš použiť a dodať svojmu profilu osobný vzhľad. Tento predmet bude odomknutý pre všetky vesmíry na tvojom účte. Upozorňujeme, že synchronizácia medzi vesmírmi môže trvať určitý čas.', 'duration_label' => 'Trvalé', 'extended_description' => 'Legendy hovoria o rozkošnom mačiatku, za ktorou sa tiahne dúha, keď letí nekonečným vesmírom. Niektorí vyvracači sa snažili vysvetliť tieto mýty ako nič iné než problém s plynovým filtračným systémom v kabíne, ale kto vie...'],
    'c54d5a8f36f20373c5bb633a109241290b2e2a7a' => ['name' => 'Avatar: Vojnový štváč', 'description' => 'Výberom tohto avatara v profile hráča ho môžeš použiť a dodať svojmu profilu osobný vzhľad. Tento predmet bude odomknutý pre všetky vesmíry na tvojom účte. Upozorňujeme, že synchronizácia medzi vesmírmi môže trvať určitý čas.', 'duration_label' => 'Trvalé', 'extended_description' => 'Tí, ktorí vládnu železnou päsťou, často veľmi dbajú na to, aby si vypestovali nebezpečnú osobnosť. Ľudia, ktorí k nim prichádzajú s prosbou alebo im vzdávajú hold, by mali okamžite spoznať, s kým majú do činenia.'],
    '99f53568108115acac2d7f7425ee2ad76a6206b8' => ['name' => 'Avatar: Mačací veliteľ', 'description' => 'Výberom tohto avatara v profile hráča ho môžeš použiť a dodať svojmu profilu osobný vzhľad. Tento predmet bude odomknutý pre všetky vesmíry na tvojom účte. Upozorňujeme, že synchronizácia medzi vesmírmi môže trvať určitý čas.', 'duration_label' => 'Trvalé', 'extended_description' => 'Rýchle reflexy môžu byť prínosom pre každého vesmírneho vládcu, zatiaľ čo roztomilý vzhľad často skrýva dôvtipnú myseľ medzi špicatými ušami.'],
    'c70f11e9543100622e3ef3bdcd57099a63f148bf' => ['name' => 'Avatar: Osud', 'description' => 'Výberom tohto avatara v profile hráča ho môžeš použiť a dodať svojmu profilu osobný vzhľad. Tento predmet bude odomknutý pre všetky vesmíry na tvojom účte. Upozorňujeme, že synchronizácia medzi vesmírmi môže trvať určitý čas.', 'duration_label' => 'Trvalé', 'extended_description' => 'Je nespočetné množstvo konfliktov, ktoré sa v rozľahlých končinách vesmíru riešili hodom kocky D20. Strany tejto kocky sú prázdne – aké rozhodnutia urobí?'],
    'ac5bd99552a23733f7b0decac45094d5bfbfedac' => ['name' => 'Avatar: Horiaci hnev', 'description' => 'Výberom tohto avatara v profile hráča ho môžeš použiť a dodať svojmu profilu osobný vzhľad. Tento predmet bude odomknutý pre všetky vesmíry na tvojom účte. Upozorňujeme, že synchronizácia medzi vesmírmi môže trvať určitý čas.', 'duration_label' => 'Trvalé', 'extended_description' => 'Niektorí vládcovia medzi hviezdami vyvolávajú strach v ľudských srdciach všade, kde sa objavia ich flotily. Len hlupák by chcel zakúsiť ich hnev.'],
    'da8b1dcf6a9defb45e456968d3c8587bf63a48b5' => ['name' => 'Limitovaný avatar: Horizont udalostí', 'description' => 'Výberom tohto avatara v profile hráča ho môžeš použiť a dodať svojmu profilu osobný vzhľad. Tento predmet bude odomknutý pre všetky vesmíry na tvojom účte. Upozorňujeme, že synchronizácia medzi vesmírmi môže trvať určitý čas.', 'duration_label' => 'Trvalé', 'extended_description' => 'Ako sa ukazuje, staré príslovie výskumníkov o odvážnom prekračovaní horizontu má svoje limity, pokiaľ ide o vesmírne cestovanie...'],
    '69719df021ec40424225f22e2edca15b799401a5' => ['name' => 'Limitovaný avatar: Hviezdny pilot', 'description' => 'Výberom tohto avatara v profile hráča ho môžeš použiť a dodať svojmu profilu osobný vzhľad. Tento predmet bude odomknutý pre všetky vesmíry na tvojom účte. Upozorňujeme, že synchronizácia medzi vesmírmi môže trvať určitý čas.', 'duration_label' => 'Trvalé', 'extended_description' => 'Sú to najtalentovanejší spolubojovníci, najostrejší piloti a najväčšie mysle, ktorí nesú odkaz ľudstva ďaleko za hviezdy.'],
    'facb9419f24c4a1fbff7dc29376c3f57c6204c1c' => ['name' => 'Limitovaný avatar: Android', 'description' => 'Výberom tohto avatara v profile hráča ho môžeš použiť a dodať svojmu profilu osobný vzhľad. Tento predmet bude odomknutý pre všetky vesmíry na tvojom účte. Upozorňujeme, že synchronizácia medzi vesmírmi môže trvať určitý čas.', 'duration_label' => 'Trvalé', 'extended_description' => 'Plne mechanické posádky môžu byť mimoriadne užitočné v nepriateľských prostrediach. Vyžadujú tiež menej nákladného priestoru na prídely, zatiaľ čo technológia rýchleho nabíjania znamená, že rekuperácia na nabíjacej stanici trvá menej času ako bežný spánok. A od zavedenia pokročilých batériových systémov už nikto nemusí znášať poníženie byť pripútaný k nabíjacímu káblu, a to ani na ľadových planétach.'],
    '74bf9741209dc8ef4f9996b8b2b7ca59001ea3a8' => ['name' => 'Limitovaný avatar: Hviezdna korytnačka', 'description' => 'Výberom tohto avatara v profile hráča ho môžeš použiť a dodať svojmu profilu osobný vzhľad. Tento predmet bude odomknutý pre všetky vesmíry na tvojom účte. Upozorňujeme, že synchronizácia medzi vesmírmi môže trvať určitý čas.', 'duration_label' => 'Trvalé', 'extended_description' => 'Hoci existencia hviezdnych korytnačiek zostáva medzi odborníkmi kontroverznou témou, zvesti o nich tvrdohlavo pretrvávajú. Správy o pozorovaniach pravidelne spájajú tento druh s hrubokožcami, plochými nebeskými telesami a všetkými možnými inými zvláštnosťami...'],
    '07a4b64949fcc593435cfaa9184290af96ffdc29' => ['name' => 'Limitovaný avatar: Nákova osudu', 'description' => 'Výberom tohto avatara v profile hráča ho môžeš použiť a dodať svojmu profilu osobný vzhľad. Tento predmet bude odomknutý pre všetky vesmíry na tvojom účte. Upozorňujeme, že synchronizácia medzi vesmírmi môže trvať určitý čas.', 'duration_label' => 'Trvalé', 'extended_description' => 'Každý vládca drží osud svojej galaktickej ríše vo svojich rukách. Tento osud si vytváraš sám, pretože o víťazstve alebo porážke rozhoduje tvoj talent a predvídavosť.'],
